 let h=surfacePatch.h;let dx=15.*mix(h.y-h.x,h.w-h.z,surfacePatch.uv.y);let dz=15.*mix(h.z-h.x,h.w-h.y,surfacePatch.uv.x);return normalize(vec3f(-dx,1.,-dz));
