    // constant-width coordinates and bound its Jacobian over the local AABB.
    let width=max(.001,obj.shape.x+obj.shape.w*clamp(p.y,-obj.shape.y,obj.shape.y));
    let oval=length(vec2f(p.x/width,p.z/obj.shape.z))-1.;
    let distance=oval*min(width,obj.shape.z);
    let q=vec2f(distance+obj.extra.x,abs(p.y)-obj.shape.y+obj.extra.x);
    // Distance bound includes derivatives of both the taper and ellipse scale.
    let lowerWidth=obj.shape.x-abs(obj.shape.w)*obj.shape.y;
    let jacobian=1.+abs(obj.shape.w)*(obj.localMax.x/lowerWidth+1.);
